import{PINS}from'./pins.mjs';import{createV5Night,mixForMinutes}from'./layer.mjs';
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function loadV5Night({fetcher=fetch,signal,image,actors,npcs,canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}){
 let dead=false,layer=null,depthRGB=[],alphas=new Map();const own=new Set(),check=()=>{if(dead||signal?.aborted)throw Error('V5_NIGHT_CANCELLED')},canvas=(w,h)=>{check();const c=canvasFactory(w,h);own.add(c);return c},release=c=>{own.delete(c);c.width=c.height=1};
 const dispose=()=>{if(dead)return;dead=true;const pending=[...own];own.clear();const old=layer;layer=null;depthRGB=[];alphas.clear();let first;try{old?.dispose()}catch(e){first=e}for(const c of pending)try{c.width=c.height=1}catch(e){first??=e}if(first)throw first};
 try{if(image.width!==1536||image.height!==1024||!npcs)throw Error('V5_NIGHT_INPUT');const bank={};for(const[p,pin]of Object.entries(PINS)){check();const r=await fetcher(new URL(p,import.meta.url),{signal});if(!r.ok)throw Error('V5_NIGHT_MISSING');const b=new Uint8Array(await r.arrayBuffer());check();if(b.length!==pin.bytes||await hash(b)!==pin.sha256)throw Error('V5_NIGHT_PIN');check();bank[p]=b}
  const copy=b=>b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength),ids=new Uint32Array(copy(bank['assets/light.u32'])),weights=new Float32Array(copy(bank['assets/light.f32'])),depthAlpha=bank['assets/depth-alpha.u8'];
  for(const gx of[104,262]){const c=canvas(80,200),g=c.getContext('2d');g.drawImage(image,gx-40,420,80,200,0,0,80,200);depthRGB.push(g.getImageData(0,0,80,200).data);release(c)}
  for(const[id,frame]of Object.entries(actors)){const c=canvas(107,107),g=c.getContext('2d');g.drawImage(frame.image??frame,0,0);const d=g.getImageData(0,0,107,107).data;alphas.set(id,Uint8Array.from({length:11449},(_,i)=>d[i*4+3]));release(c)}
  const c=canvas(360,300),g=c.getContext('2d');g.imageSmoothingEnabled=false;for(const r of npcs.drawLayers(g,[0,420]))r.draw();const a=g.getImageData(0,0,360,300).data,npcAlpha=Uint8Array.from(ids,id=>{const x=id%1536,y=Math.floor(id/1536)-420;return x>=0&&x<360&&y>=0&&y<300?a[(y*360+x)*4+3]:0});release(c);
  layer=createV5Night({ids,weights,depthAlpha,npcAlpha,poolMultiplier:1.6});check();
  return Object.freeze({depthLayers(ctx,origin){check();return[104,262].map((gx,k)=>({y:600,draw(){check();const x=gx-40-origin[0],y=420-origin[1];if(x>=960||x+80<=0||y>=540||y+200<=0)return;const frame=ctx.getImageData(x,y,80,200);for(let i=0;i<16000;i++){const a=depthAlpha[i]/255;if(a)for(let c=0;c<3;c++)frame.data[i*4+c]=Math.round(depthRGB[k][i*4+c]*a+frame.data[i*4+c]*(1-a))}ctx.putImageData(frame,x,y)}}))},apply(ctx,origin,{foot,frame,minutes=720,lights=true,rest=false}){check();if(rest||mixForMinutes(minutes)===0)return{mix:0,rows:0};const a=alphas.get('actor:'+frame);if(!a)throw Error('V5_NIGHT_ACTOR');const im=ctx.getImageData(0,0,960,540),out=layer.apply(im.data,origin,{foot,minutes,lights,rest,actorAlpha:a,actorOrigin:[foot[0]-origin[0]-53,foot[1]-origin[1]-90]});ctx.putImageData(im,0,0);return out},dispose});
 }catch(e){try{dispose()}catch{}throw e}
}
